# hi — bash integration (generated by `hi init bash`)
# Recommended: add `eval "$(hi init bash)"` to ~/.bashrc instead of sourcing this file directly.
hi() {
  if [[ $# -eq 0 ]]; then
    command hi
    return
  fi
  local cmd
  cmd=$(command hi "$@" 2>/tmp/hi-err)
  local code=$?
  if [[ $code -ne 0 ]]; then
    cat /tmp/hi-err >&2
    return $code
  fi
  if [[ -n "$cmd" ]]; then
    printf "\n  \033[1;32m%s\033[0m\n\n" "$cmd"
    if command -v pbcopy &>/dev/null; then
      printf '%s' "$cmd" | pbcopy && echo "  ✓ Copied to clipboard — ⌘V to paste"
    elif command -v xclip &>/dev/null; then
      printf '%s' "$cmd" | xclip -selection clipboard && echo "  ✓ Copied — Ctrl+Shift+V to paste"
    fi
    history -s "$cmd"
  fi
}
